$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$mp=Join-Path $root 'port-changes.json';$m=Get-Content $mp -Raw|ConvertFrom-Json
$targets=@(
 [pscustomobject]@{rel='content/logistics/packager/PackagerBlockEntity.java';changes=@([pscustomobject]@{from='import java.util.List;';to="import java.util.ArrayList;`nimport java.util.List;"},[pscustomobject]@{from='contents.getSlots();';to='contents.getSlots().size();'});status='Original package unwrapping retained with the Fabric ItemStackHandler slot-list API.'},
 [pscustomobject]@{rel='content/logistics/factoryBoard/FactoryPanelConnectionHandler.java';changes=@([pscustomobject]@{from="import com.simibubi.create.foundation.utility.CreateLang;`n";to=''},[pscustomobject]@{from='mc.player.displayClientMessage(CreateLang';to='mc.player.displayClientMessage(Lang'});status='Original Factory Panel connection interaction retained through baseline language and client outliner helpers.'},
 [pscustomobject]@{rel='content/logistics/stockTicker/StockTickerBlock.java';changes=@([pscustomobject]@{from='return onBlockEntityUseItemOn(pLevel, pPos, stbe -> {';to='return onBlockEntityUse(pLevel, pPos, stbe -> {'},[pscustomobject]@{from='ItemStack stack = resource.toStack(';to='ItemStack paymentStack = resource.toStack('},[pscustomobject]@{from='placeItemBackInInventory(stack);';to='placeItemBackInInventory(paymentStack);'});status='Original Stock Ticker payment/menu interaction adapted through the Fabric baseline IBE helper.'},
 [pscustomobject]@{rel='content/logistics/packagePort/postbox/PostboxBlock.java';changes=@([pscustomobject]@{from='return onBlockEntityUse(level, pos, be -> be.use(player).result());';to='return onBlockEntityUse(level, pos, be -> be.use(player)).result();'});status='Original Postbox interaction adapted through the Fabric baseline IBE helper.'},
 [pscustomobject]@{rel='content/logistics/tableCloth/TableClothBlock.java';changes=@([pscustomobject]@{from='return onBlockEntityUseItemOn(world, pos, dcbe -> dcbe.use(player, ray));';to='return onBlockEntityUse(world, pos, dcbe -> dcbe.use(player, ray).consumesAction() ? ItemInteractionResult.SUCCESS : ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION);'});status='Original Table Cloth placement/shop interaction adapted through the Fabric baseline IBE helper.'},
 [pscustomobject]@{rel='compat/computercraft/implementation/peripherals/TableClothShopPeripheral.java';changes=@([pscustomobject]@{from='import com.simibubi.create.content.logistics.tableCloth.TableClothBlockEntity;';to="import com.simibubi.create.content.logistics.tableCloth.TableClothBlockEntity;`nimport com.simibubi.create.content.logistics.redstoneRequester.AutoRequestData;`nimport com.simibubi.create.content.logistics.redstoneRequester.AutoRequestData.Mutable;"});status='Official ComputerCraft Table Cloth shop peripheral adapted to immutable AutoRequestData accessors.'}
)
foreach($t in $targets){$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$x=[IO.File]::ReadAllText($p);foreach($c in $t.changes){if(-not$x.Contains($c.from)){throw "Increment gap anchor missing in $($t.rel): $($c.from)"};$x=$x.Replace($c.from,$c.to)};[IO.File]::WriteAllText($p,$x,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;$e.changes=@($e.changes)+$t.changes;if($e.PSObject.Properties.Name -contains 'status'){$e.status=$t.status}else{$e|Add-Member -NotePropertyName status -NotePropertyValue $t.status}}
$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Closed the incremental Fabric integration gaps.'
